    actor() {
      late = new Promise((resolve) =>
        setTimeout(() => resolve(ActorContext.current()), 5),
      );
      return Promise.resolve({ actor: ActorContext.current() }).then(
        async (value) => {
          await Promise.resolve();
          return { ...value, afterAwait: ActorContext.current() };
