    for (let i = 0; i < MCP_LIMITS.failuresPerWindow; i += 1) {
      expect(
        (
          await rpc(
            'tools/list',
            {},
            oauthSession(String.fromCharCode(97 + (i % 26))) + i,
          )
        ).status,
