    expect(grpcAuthorize.mock.calls.length).toBe(calls);
    expect(await authCount('rate_limited')).toBe(1);
  });

  it('answers 503 when too many decisions are in flight', async () => {
    await boot();
    (auth as unknown as { inFlight: number }).inFlight =
      MCP_LIMITS.maxConcurrentDecisions;
    expect((await rpc('tools/list', {}, oauthSession('n'))).status).toBe(503);
  });

  it('uses test auth when it is enabled, and the credential never reaches logs or metrics', async () => {
    await boot({ testAuth: true });
    expect(await toolNames(accessToken)).toEqual([
      'whoami',
      'list_capabilities',
      'call_capability',
    ]);
    expect(grpcAuthorize).not.toHaveBeenCalled();
    const exposition = await metrics.registry.metrics();
    for (const secret of [accessToken, 'pmp_pat_', 'q'.repeat(20)]) {
      expect(exposition).not.toContain(secret);
      expect(logged.join('\n')).not.toContain(secret);
    }
  });

  it('refuses an oversized body, other methods on /mcp, and a malformed request', async () => {
    await boot();
    const big = await rpc('tools/list', {
      padding: 'p'.repeat(MCP_LIMITS.maxRequestBytes),
    });
    expect(big.status).toBe(413);
    expect(big.body).toEqual({ error: 'payload_too_large' });
    for (const method of ['get', 'delete'] as const) {
      const refused = await request(app.getHttpServer())[method]('/mcp');
      expect(refused.status).toBe(405);
      expect(refused.headers.allow).toBe('POST');
    }
    const broken = await rpc('no/such/method');
    expect(broken.body.error.code).toBe(-32601);
  });

  it('answers 500 without detail when something unexpected fails', async () => {
    await boot();
    jest
      .spyOn(auth, 'authenticate')
      .mockRejectedValueOnce(new TypeError('boom'));
    const failed = await rpc('tools/list');
    expect(failed.status).toBe(500);
    expect(failed.body).toEqual({ error: 'internal' });
    expect(logged.join('\n')).toContain('MCP request failed: TypeError');
  });

  it('leaves a response the transport already started alone, and names a non-Error failure as unknown', async () => {
    await boot();
    jest
      .spyOn(StreamableHTTPServerTransport.prototype, 'handleRequest')
      .mockImplementationOnce((_request, response) => {
        response.writeHead(200, { 'content-type': 'application/json' });
        response.end('{"partial":true}');
        return Promise.reject(new Error('after the answer started'));
      });
    const started = await rpc('tools/list');
    expect(started.status).toBe(200);
    expect(started.body).toEqual({ partial: true });
    jest.spyOn(auth, 'authenticate').mockRejectedValueOnce('a string');
    expect((await rpc('tools/list')).status).toBe(500);
    expect(logged.join('\n')).toContain('MCP request failed: unknown');
  });

  describe('actions that matter re-authorize with no cache', () => {
    const operator = () => [
      ALCANTARA_PERMISSIONS.access,
      ALCANTARA_PERMISSIONS.radio.operate,
      ALCANTARA_PERMISSIONS.song.manage,
    ];

    it('asks Pompeii again for every on-air and destructive call, even with a warm cache', async () => {
      await boot({ executor: true });
      answer.effective_permissions = operator();
      await rpc('tools/list');
      expect(grpcAuthorize).toHaveBeenCalledTimes(1);
      expect((await callTool('sample_on_air', KEY)).body).toEqual({
        executed: true,
      });
      // The request itself uses the cached allow; the action asks once more.
      expect(grpcAuthorize).toHaveBeenCalledTimes(2);
      expect(
        (
          await callTool('call_capability', {
            name: 'sample_delete',
            arguments: KEY,
          })
        ).body,
      ).toEqual({ executed: true });
      expect(grpcAuthorize).toHaveBeenCalledTimes(3);
      // A reversible write may use the cached decision.
      await callTool('sample_write', { id: 1, ...KEY });
      expect(grpcAuthorize).toHaveBeenCalledTimes(3);
      expect(executor!.execute).toHaveBeenCalledWith(
        expect.objectContaining({ name: 'sample_on_air' }),
        KEY,
        expect.objectContaining({
          principal: expect.objectContaining({ subject: 'subject-1' }),
        }),
      );
    });

    it('refuses the very next on-air call once the token is revoked, without running it, and the next request too', async () => {
      await boot({ executor: true });
      answer.effective_permissions = operator();
      await rpc('tools/list');
      const revoked = () => {
        answer = {
          authenticated: false,
          allowed: false,
          reason: 'DENY_REVOKED',
        };
      };
      // The cached allow would still list tools; the action asks afresh.
      const call = rpc('tools/call', {
        name: 'sample_on_air',
        arguments: KEY,
      });
      revoked();
      const refused = await call;
